-- The first partner template, TAYGA GRUP, with the logo from their CV form, so
-- the cabinet offers it from the start. Added only when no template is saved,
-- so a template a manager already saved is never replaced. The time is stored
-- in UTC, as Prisma reads it.
INSERT INTO "partner_templates" ("name", "header", "contacts", "logo", "updated_at")
SELECT 'TAYGA GRUP', '', '', decode('', 'base64'), (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
WHERE NOT EXISTS (SELECT 1 FROM "partner_templates");
